head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil01010";
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — codeList

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_16", fn: function(){ return (!(String(((dma_pageContext.get("codeList") ?? "")) === null ? '' : ((dma_pageContext.get("codeList") ?? ""))).length === 0)); } }, { id: "tr_17", fn: function(){ return (!(String(((dma_pageContext.get("codeList") ?? "")) === null ? '' : ((dma_pageContext.get("codeList") ?? ""))).length === 0)); } }, { id: "c_otherwise_29", fn: function(){ return (!((!(String(((dma_pageContext.get("codeList") ?? "")) === null ? '' : ((dma_pageContext.get("codeList") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("cdNm") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const formObj = (document.codeForm || { elements: [] });
        const openerOjb = scwin.frame.document.comFrm;
        $c.util.getComponent("ipt_formKey").setValue(openerOjb.formKey.value);
        $c.util.getComponent("ipt_keyValue").setValue(openerOjb.keyValue.value);
        $c.util.getComponent("ipt_returnKey").setValue(openerOjb.returnKey.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01010.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil01010: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil01010' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil01010' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil01010' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil01010.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_noSelected_onclick
 * @description 「-|-」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_noSelected_onclick = function(e){
    try {
        scwin.noSelected()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01010.ipt_noSelected_onclick' }); }
};

/**
 * @method
 * @name btn_selected_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selected_onclick = async function(e){
    try {
        await scwin.selected()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil01010.btn_selected_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil01010.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selected
 * @description selected 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function () {
    const formObj = (document.codeForm || { elements: [] });
    let ndx = "";
    const selectArr = new Array(2);
    let code = "";
    let name = "";
    if (((!$c.util.getComponent('ipt_noSelected') || typeof $c.util.getComponent('ipt_noSelected').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_noSelected'), false) : ($c.util.getComponent('ipt_noSelected').getValue() !== null && String($c.util.getComponent('ipt_noSelected').getValue()) !== '')) === false) {
        for (i = 0; i < $c.util.getComponent("slc_selIndcode").length; i++) {
            if ($c.util.getComponent("slc_selIndcode").options[i].selected) {
                if (name.length === "") {
                    name = $c.util.getComponent("slc_selIndcode").options[i].text;
                    code = $c.util.getComponent("slc_selIndcode").options[i].value;
                } else {
                    name = name + ",\n" + $c.util.getComponent("slc_selIndcode").options[i].text;
                    code = code + "," + $c.util.getComponent("slc_selIndcode").options[i].value;
                }
                ndx++;
            }
        }
        if (ndx === 0) {
            await $c.win.alert("입력할 사유를  선택하십시오");
            return;
        } else {
            scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), code, name);
            $c.win.closePopup();
        }
    } else {
        code = "-";
        name = "-";
        scwin.frame.fn_setSelectedData($c.util.getComponent("ipt_formKey").getValue(), $c.util.getComponent("ipt_keyValue").getValue(), decodeURIComponent($c.util.getComponent("ipt_returnKey").getValue()), code, name);
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name noSelected
 * @description no Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.noSelected = function () {
    const formObj = (document.codeForm || { elements: [] });
    if (((!$c.util.getComponent('ipt_noSelected') || typeof $c.util.getComponent('ipt_noSelected').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_noSelected'), false) : ($c.util.getComponent('ipt_noSelected').getValue() !== null && String($c.util.getComponent('ipt_noSelected').getValue()) !== '')) === true) {
        $c.util.getComponent('slc_selIndcode').setDisabled(true);
    } else {
        $c.util.getComponent('slc_selIndcode').setDisabled(false);
    }
};
